// Imports employees from data/employees.seed.json (generated by tools/parse_pdfs.py)
// into the employees table. Passwords are hashed with bcrypt. Re-running updates
// existing rows (matched by emp_id) without touching their session history.
require('dotenv').config();
const fs = require('fs');
const path = require('path');
const bcrypt = require('bcryptjs');
const { pool } = require('../src/db');

const SEED = path.join(__dirname, '..', 'data', 'employees.seed.json');

(async () => {
  let inserted = 0;
  let updated = 0;
  try {
    const rows = JSON.parse(fs.readFileSync(SEED, 'utf8'));
    console.log(`Importing ${rows.length} employees from ${SEED} ...`);

    for (const r of rows) {
      const empId = (r.emp_id || '').trim();
      const username = (r.device_username || '').trim();
      const password = (r.device_password || '').trim();
      if (!empId || !username || !password) {
        console.warn(`  ! skipping record with missing key fields: ${JSON.stringify(r).slice(0, 80)}`);
        continue;
      }
      const hash = bcrypt.hashSync(password, 10);
      const email = (r.email || '').replace(/\s+/g, ''); // some PDFs have a stray space before @

      const res = await pool.query(
        `INSERT INTO employees
           (emp_id, name, designation, device_username, password_hash,
            email, team, reporting_manager, team_leader)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
         ON CONFLICT (emp_id) DO UPDATE SET
           name              = EXCLUDED.name,
           designation       = EXCLUDED.designation,
           device_username   = EXCLUDED.device_username,
           password_hash     = EXCLUDED.password_hash,
           email             = EXCLUDED.email,
           team              = EXCLUDED.team,
           reporting_manager = EXCLUDED.reporting_manager,
           team_leader       = EXCLUDED.team_leader,
           updated_at        = now()
         RETURNING (xmax = 0) AS inserted`,
        [empId, r.name || '', r.designation || '', username.toLowerCase(), hash,
         email, r.team || '', r.reporting_manager || '', r.team_leader || '']
      );
      if (res.rows[0].inserted) inserted++; else updated++;
    }
    console.log(`✓ Done. ${inserted} inserted, ${updated} updated.`);
  } catch (err) {
    console.error('Import failed:', err.message);
    process.exitCode = 1;
  } finally {
    await pool.end();
  }
})();
